CREATE TABLE orders (
  order_id    integer PRIMARY KEY,
  customer    text NOT NULL,
  amount      numeric(10,2) NOT NULL,
  status      text NOT NULL DEFAULT 'NEW'
);
INSERT INTO orders VALUES
  (1, 'Asha',  1200.00, 'NEW'),
  (2, 'Ravi',   850.50, 'PAID'),
  (3, 'Meena', 4300.00, 'NEW');

# Terminal 1: a long running query
PGAPPNAME=billing psql -h localhost -U app_user -d shopdb
shopdb=> SELECT pg_sleep(600);

# Terminal 2: a transaction that is left open
PGAPPNAME=report psql -h localhost -U app_user -d shopdb
shopdb=> BEGIN;
shopdb=*> UPDATE orders SET status = 'PAID' WHERE order_id = 1;

# Terminal 3: an update of the same row (it will wait)
PGAPPNAME=checkout psql -h localhost -U app_user -d shopdb
shopdb=> UPDATE orders SET amount = 1250.00 WHERE order_id = 1;

# Terminal 4: a session that just sits connected
PGAPPNAME=webapp psql -h localhost -U app_user -d shopdb

SELECT pid, usename, state, query
  FROM pg_stat_activity
 WHERE usename = 'app_user';
SELECT pg_terminate_backend(3293);

SELECT count(*) AS sessions_left
  FROM pg_stat_activity
 WHERE datname = 'shopdb';

SELECT datname, datallowconn, datconnlimit
  FROM pg_database WHERE datname = 'shopdb';

ALTER ROLE app_user CONNECTION LIMIT 2;
ALTER DATABASE shopdb CONNECTION LIMIT 50;

SELECT rolname, rolconnlimit FROM pg_roles WHERE rolname = 'app_user';
SELECT datname, datconnlimit FROM pg_database WHERE datname = 'shopdb';

